-- Setup G · Addon Farm Breeding · Standard Analysis: header @STEM_MSTDANALYSIS + detail @STEM_DSTDANALYSIS (per umur). Entity SL: STEM_MSTDANALYSIS.
-- _Detail = baris detail digabung (baris dipisah '¦', kolom '^', urut LineId): dibandingkan antar DB, tidak dikirim sebagai field; dipecah lagi saat baris BARU dibuat.
-- Dokumen tidak punya kode: dicocokkan lewat deskripsi; DocEntry tujuan dipakai sebagai _key.
SELECT H."DocEntry" AS "_key", H."U_StdAnsDesc", TO_VARCHAR(H."U_DocDate", 'YYYY-MM-DD') AS "U_DocDate", H."U_Remarks",
       (SELECT STRING_AGG(IFNULL(CAST(D."U_Age" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_ABWFemale_DarkOut" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_ABWFemale_OpenSide" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_ABWMale" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_DeathRate" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_DeathRate_Cum" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_DeathRate_M" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_DeathRate_M_Cum" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_ST_ANJ" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_ST_ANJE" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_FeedConsDaily" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_FeedConsCum" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_FeedConsDaily_M" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_FeedConsCum_M" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_Uniformity" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_Uniformity_M" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_TotalEgg_HW" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_HatchEgg_HW" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_TotalEgg_HH" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_HatchEgg_HH" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_TotalEgg_HH_B" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_HatchEgg_HH_B" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_HEWeekly" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_WeeklyHatch" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_Chick_HH" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_Chick_HH_E" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_Hatchability" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_Fertility" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_HatchOfFertile" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_ChickNo" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_FertilityW" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_HatchOfFertileW" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_ChickNoW" AS NVARCHAR(100)),'') || '^' || IFNULL(CAST(D."U_EggWeight" AS NVARCHAR(100)),''), '¦' ORDER BY D."LineId") FROM "@STEM_DSTDANALYSIS" D WHERE D."DocEntry" = H."DocEntry") AS "_Detail"
FROM "@STEM_MSTDANALYSIS" H
ORDER BY H."DocEntry"
